    logger.error(
      `"${project}" does not exists. Please use \`$ scaffdog init\` to setup the scaffdog project.`,
    );
    return 1;
  }

  // name
  let name: string;
  if (args.name) {
    if (!validFilename(args.name)) {
      logger.error('Should be a valid filename!');
      return 1;
